      ],
    };
  },

  computed: {
    registeredComponents(): string[] {
      return Object.keys(COMPAT_OVERRIDES).sort();
    },
    componentCount(): number {
      return Object.keys(COMPAT_OVERRIDES).length;
    },
  },

  watch: {
    isDark(val: boolean) {
      document.body.classList.toggle('body--dark', val);
    },
  },

  methods: {
    toWrapperName(tag: string): string {
      return tag
        .split('-')
        .map((part, i) => (i === 0 && part === 'q' ? 'Q' : part.charAt(0).toUpperCase() + part.slice(1)))
        .join('') + 'Compat';
    },
  },
});
